def clean_mask(im,region=None,rope=False,strict=False,minheight=58,bridge=None):
 """Extract opaque bodies while keeping white shirts and saturated costumes.
 In rope sheets, interpolate narrow scenery bands before silhouette extraction.
 """
 import numpy as np
 from scipy import ndimage as ndi
 from PIL import Image
 a=np.array(im).copy();v=a.astype('int16');h,w=a.shape[:2]
 fg=(v.min(2)<(180 if rope else 118))|((v.max(2)-v.min(2))>45)
 if rope:
  red=(v[:,:,0]>95)&(v[:,:,0]>v[:,:,1]*1.55)&(v[:,:,0]>v[:,:,2]*1.6)
  if region is not None:fg&=region
  support=ndi.binary_opening(fg,structure=np.ones((21,1),dtype=bool))
  # Thin horizontal ropes differ from tall red costume panels. Repair only
  # their narrow pixel runs, keeping the original body silhouette intact.
  thin=red&~ndi.binary_opening(red,structure=np.ones((15,1),dtype=bool))
  repair=ndi.binary_dilation(ndi.binary_opening(thin,structure=np.ones((1,15),dtype=bool)),iterations=2)
  yy=np.arange(h)[:,None];xx=np.arange(w)[None,:]
  up=np.maximum.accumulate(np.where(~repair,yy,0),axis=0)
  dn=np.minimum.accumulate(np.where(~repair,yy,h-1)[::-1],axis=0)[::-1]
  gap=np.maximum(1,dn-up)
  blend=(a[up,xx].astype(float)*(dn-yy)[:,:,None]+a[dn,xx].astype(float)*(yy-up)[:,:,None])/gap[:,:,None]
  can=repair&(gap<28);a[can]=blend.astype('uint8')[can];v=a.astype('int16')
  fg=(v.min(2)<180)|((v.max(2)-v.min(2))>45)
  fg[repair&~ndi.binary_dilation(support,iterations=1)]=False
  blue=(v.min(2)>80)&(v[:,:,1]>v[:,:,0]+15)&(v[:,:,2]>v[:,:,1]+15)&(np.arange(h)[:,None]>h*.73)
  fg&=~blue
 if region is not None:fg&=region
 fg=ndi.binary_closing(fg,iterations=1)
 if region is not None:fg&=region
 labels,n=ndi.label(fg);objects=ndi.find_objects(labels);items=[]
 if rope:
  sizes=np.bincount(labels.ravel());keep=sizes>400;keep[0]=False
  for k,s in enumerate(objects,1):
   if s and (s[1].stop-s[1].start<6 or s[0].stop-s[0].start<5):keep[k]=False
  fg=keep[labels];ys,xs=np.where(fg)
  if not len(xs):return []
  objects=[(slice(ys.min(),ys.max()+1),slice(xs.min(),xs.max()+1))]
 for k,s in enumerate(objects,1):
  if not s:continue
  ys,xs=s;bh=ys.stop-ys.start;bw=xs.stop-xs.start;base=fg[s] if rope else labels[s]==k;area=int(base.sum())
  if bh<minheight or bw<35 or area<2500 or area/(bh*bw)<.12:continue
  holes=ndi.binary_fill_holes(base)&~base;hl,hn=ndi.label(holes);sizes=np.bincount(hl.ravel());small=sizes<1500;small[0]=False
  upper=np.arange(bh)[:,None]<bh*.62
  mask=base|(holes&(small[hl]|upper))
  items.append(dict(image=Image.fromarray(np.dstack((a[s],mask.astype('uint8')*255))),x=int(xs.start),y=int(ys.start),w=int(bw),h=int(bh),area=area))
 return items
